"use client";

import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { focusRing, primaryFill } from "./_shared";

/**
 * Airy docs IconButton: a single glyph in the same materials as the Button.
 *
 * Round by default, like every Airy docs pill; the square shape keeps a
 * corner that grows with the button. The default is a hairline circle on
 * white, like the copy and theme buttons in a docs header. `primary` is the
 * flat green, and ghost is the quiet choice for toolbars and code headers.
 */
const iconButtonVariants = cva(
  [
    "relative inline-flex shrink-0 select-none items-center justify-center",
    "transition-[background-color,color,border-color] duration-fast ease-out",
    focusRing,
    "disabled:pointer-events-none disabled:border-transparent disabled:bg-muted disabled:text-(--foreground-disabled)",
    "data-[disabled]:pointer-events-none data-[disabled]:border-transparent data-[disabled]:bg-muted data-[disabled]:text-(--foreground-disabled)",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default:
          "border border-border bg-background text-(--foreground-secondary) hover:bg-secondary hover:text-foreground",
        primary: primaryFill,
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-muted",
        ghost: "bg-transparent text-muted-foreground hover:bg-secondary hover:text-foreground",
        destructive:
          "bg-destructive text-destructive-foreground hover:bg-destructive/90",
        outline:
          "border border-(--line-strong) bg-background text-foreground hover:bg-secondary",
      },
      size: {
        xs: "size-7 rounded-sm [&_svg]:size-3.5",
        sm: "size-8 rounded-md [&_svg]:size-4",
        default: "size-9 rounded-md [&_svg]:size-4",
        lg: "size-11 rounded-lg [&_svg]:size-5",
        xl: "size-12 rounded-xl [&_svg]:size-5",
      },
      corners: {
        square: "",
        circle: "rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
      corners: "circle",
    },
  },
);

/** Props for the IconButton. Give it an `aria-label`, since the glyph carries no text. */
export interface IconButtonProps
  extends
    Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof iconButtonVariants> {
  className?: string;
}

const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  ({ className, variant, size, corners, ...props }, ref) => (
    <ButtonPrimitive
      ref={ref}
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, size, corners, className }))}
      {...props}
    />
  ),
);
IconButton.displayName = "IconButton";

export { IconButton, iconButtonVariants };
